import * as THREE from 'three';
import './style.css';

const $ = (s) => document.querySelector(s);
const ui = { credits: $('#credits'), kills: $('#kills'), objective: $('#objective-fill'), wave: $('#wave'), health: $('#health-fill'), healthText: $('#health-text'), armor: $('#armor-fill'), armorText: $('#armor-text'), xp: $('#xp-fill'), xpText: $('#xp-text'), classLabel: $('#class-label'), ammo: $('#ammo'), toast: $('#toast'), terminal: $('#terminal'), content: $('#terminal-content'), resources: $('#resource-summary'), interaction: $('#interaction') };
const game = { credits:450, scrap:0, crystal:0, fiber:0, kills:0, hp:100, armor:25, xp:0, level:1, classId:'vanguard', ammo:30, reserve:120, weapon:'RANGER', damage:25, speed:1, armorMax:25, started:false, terminal:false, selectedTab:'classes', keys:{}, yaw:0, pitch:0, fireTimer:0, reload:false, resources:[], enemies:[], drops:[], buildings:[], lastDamage:0 };
const classes = [
 {id:'vanguard',name:'VANGUARD',icon:'✳',role:'FRONTLINE ASSAULT',desc:'A disciplined shock trooper built to hold the line.',hp:100,armor:25,speed:1,weapon:'RANGER',perk:'+15% weapon damage'},
 {id:'medic',name:'FIELD MEDIC',icon:'✚',role:'COMBAT SUPPORT',desc:'Keeps the squad on its feet under heavy fire.',hp:125,armor:20,speed:.98,weapon:'PULSE',perk:'Regenerate health over time'},
 {id:'ranger',name:'RANGER',icon:'⌖',role:'SCOUT & MARKSMAN',desc:'Fast, agile, and deadly at a distance.',hp:90,armor:15,speed:1.28,weapon:'LONGSHOT',perk:'+25% movement speed'},
 {id:'engineer',name:'ENGINEER',icon:'⚙',role:'FIELD BUILDER',desc:'Salvage specialist with reinforced plating.',hp:110,armor:35,speed:.92,weapon:'BREACHER',perk:'Harvest 2× resources'},
 {id:'recon',name:'RECON',icon:'◉',role:'STEALTH OPERATIVE',desc:'A quiet hunter who strikes before being seen.',hp:95,armor:20,speed:1.12,weapon:'SPECTRE',perk:'+50% scrap from kills'}
];
const recipes = [
 {id:'armor',name:'Reinforced Armor',icon:'⬡',desc:'Restore 45 armor points.',cost:{scrap:18,crystal:0,fiber:5},action:'armor'},
 {id:'medkit',name:'Combat Medkit',icon:'✚',desc:'Restore 50 health points.',cost:{scrap:12,crystal:0,fiber:8},action:'medkit'},
 {id:'ammo',name:'Rifle Ammo Pack',icon:'▤',desc:'Refill 60 rounds for your weapon.',cost:{scrap:10,crystal:0,fiber:0},action:'ammo'},
 {id:'rifle',name:'Pulse Carbine',icon:'⌁',desc:'Craft a hard-hitting energy rifle.',cost:{scrap:40,crystal:8,fiber:0},action:'rifle'},
 {id:'wall',name:'Fortified Cover',icon:'▦',desc:'Deploy a buildable concrete barrier.',cost:{scrap:25,crystal:0,fiber:5},action:'wall'},
 {id:'turret',name:'Auto-Turret',icon:'◈',desc:'A compact autonomous defense unit.',cost:{scrap:55,crystal:12,fiber:5},action:'turret'}
];
const armory = [
 {id:'rifle',name:'Pulse Carbine',icon:'⌁',desc:'Energy weapon · 40 damage · 24-round mag.',cost:{scrap:40,crystal:8,fiber:0},action:'rifle'},
 {id:'armor2',name:'Titanium Plating',icon:'⬡',desc:'Upgrade armor capacity by 30 points.',cost:{scrap:35,crystal:4,fiber:10},action:'armor2'},
 {id:'damage',name:'Weapon Calibration',icon:'⌖',desc:'Permanently increase damage by 6.',cost:{scrap:30,crystal:5,fiber:0},action:'damage'},
 {id:'speed',name:'Kinetic Servos',icon:'➤',desc:'Permanently increase movement speed.',cost:{scrap:25,crystal:0,fiber:12},action:'speed'}
];

const scene = new THREE.Scene();
scene.background = new THREE.Color('#9fae96');
scene.fog = new THREE.FogExp2('#9fae96', .012);
const camera = new THREE.PerspectiveCamera(54, innerWidth/innerHeight, .1, 180);
const renderer = new THREE.WebGLRenderer({canvas:$('#game'),antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight('#d8e6c8','#354438',2.1));
const sun = new THREE.DirectionalLight('#fff0d4',3.3); sun.position.set(-18,32,12); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-38; sun.shadow.camera.right=38; sun.shadow.camera.top=38; sun.shadow.camera.bottom=-38; scene.add(sun);
const mats={ground:new THREE.MeshStandardMaterial({color:'#737d5a',roughness:1}),sand:new THREE.MeshStandardMaterial({color:'#a28d63',roughness:1}),dark:new THREE.MeshStandardMaterial({color:'#394338',roughness:1}),metal:new THREE.MeshStandardMaterial({color:'#58675e',roughness:.65,metalness:.4}),rust:new THREE.MeshStandardMaterial({color:'#97614a',roughness:.9}),lime:new THREE.MeshStandardMaterial({color:'#d4fa55',emissive:'#809e25',emissiveIntensity:.3}),blue:new THREE.MeshStandardMaterial({color:'#73bdd0',emissive:'#2b687d',emissiveIntensity:.45}),enemy:new THREE.MeshStandardMaterial({color:'#903d34',roughness:.75}),enemyGlow:new THREE.MeshStandardMaterial({color:'#ff593e',emissive:'#ff341f',emissiveIntensity:2}),wood:new THREE.MeshStandardMaterial({color:'#806c4b',roughness:1}),leaf:new THREE.MeshStandardMaterial({color:'#465d3d',roughness:1})};
function box(parent,x,y,z,sx,sy,sz,mat,shadow=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);m.position.set(x,y,z);m.castShadow=shadow;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,mat,seg=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
// Chunky frontier terrain: sand patches, cracked plates, block-built outpost.
const ground=box(scene,0,-.55,0,120,1,120,mats.ground,false); ground.receiveShadow=true;
for(let i=0;i<80;i++){const x=(Math.random()-.5)*95,z=(Math.random()-.5)*95;if(Math.abs(x)<12&&Math.abs(z)<12)continue;const size=1+Math.random()*4;box(scene,x,-.03,z,size,.12,size*(.5+Math.random()),Math.random()>.5?mats.sand:mats.dark,false)}
function createBuilding(x,z,sx,sz,kind='outpost'){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);game.buildings.push(g);
 box(g,0,1.5,0,sx,3,sz,mats.dark);box(g,0,3.05,0,sx+.3,.2,sz+.3,mats.metal);box(g,0,.12,sz/2+.03,sx*.34,.24,.1,mats.rust);
 for(const a of [-1,1]){box(g,a*sx*.39,1.9,-sz*.18,.22,2.4,.22,mats.metal);box(g,a*sx*.39,1.9,sz*.18,.22,2.4,.22,mats.metal)}
 if(kind==='outpost'){box(g,0,2.45,-sz*.5-.04,sx*.54,.42,.12,mats.rust);box(g,0,2.45,-sz*.5-.12,sx*.18,.08,.08,mats.lime);cylinder(g,-sx*.23,3.8,0,.08,.08,1.4,mats.metal);box(g,-sx*.23,4.5,0,.8,.42,.04,mats.rust)}
 else {for(let j=0;j<2;j++)box(g,(j-.5)*sx*.45,1.6,-sz*.5-.04,sx*.2,1.2,.1,mats.wood)}
 return g;
}
createBuilding(-8,-7,8,7,'outpost');createBuilding(8,-5,6,5,'shelter');createBuilding(-7,8,7,5,'shelter');createBuilding(10,9,5,7,'shelter');
// Rocky ridges and blocky scrub trees frame the playable basin.
for(let i=0;i<34;i++){const angle=i/34*Math.PI*2,r=35+Math.random()*10,x=Math.cos(angle)*r,z=Math.sin(angle)*r,h=2+Math.random()*5;box(scene,x,h/2-.1,z,2+Math.random()*5,h,2+Math.random()*4,i%3?mats.dark:mats.rust)}
for(let i=0;i<24;i++){const x=(Math.random()-.5)*58,z=(Math.random()-.5)*58;if(Math.abs(x)<13&&Math.abs(z)<13)continue;const trunk=cylinder(scene,x,.65,z,.22,.28,1.3,mats.wood,5);const crown=box(scene,x,1.8,z,1.7,1.4,1.7,mats.leaf);crown.rotation.y=Math.random()}
// Player body, armor, helmet and visible rifle assembled from primitive geometry.
const player=new THREE.Group();scene.add(player);player.position.set(0,0,4);
const body=new THREE.Group();player.add(body);
box(body,0,.9,0,.68,.85,.42,mats.metal);box(body,0,.95,-.23,.48,.48,.1,mats.dark);box(body,0,1.52,0,.47,.42,.45,mats.rust);box(body,0,1.73,0,.48,.15,.46,mats.metal);box(body,0,1.52,-.245,.23,.09,.04,mats.lime);
for(const side of [-1,1]){box(body,side*.44,.98,0,.23,.43,.38,mats.rust);box(body,side*.2,.36,0,.24,.65,.3,mats.dark);box(body,side*.2,.1,-.03,.3,.2,.4,mats.metal)}
const rifle=new THREE.Group();body.add(rifle);box(rifle,.45,1.02,-.48,.13,.15,.8,mats.dark);box(rifle,.45,1.1,-.78,.09,.06,.36,mats.metal);box(rifle,.45,.89,-.42,.09,.18,.12,mats.rust);box(rifle,.45,1.14,-.38,.06,.06,.16,mats.lime);
const muzzleFlash=new THREE.PointLight('#ffcb6b',0,4);muzzleFlash.position.set(.45,1.08,-1.05);body.add(muzzleFlash);
const playerMat=mats.rust;
// Camera ray targeting is constrained to hostile units, never targets real systems.
const raycaster=new THREE.Raycaster();const mouseNdc=new THREE.Vector2(0,0);const groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);const aimPoint=new THREE.Vector3();
function createResource(x,z,type){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);g.userData={type,available:true};if(type==='scrap'){box(g,0,.28,0,.9,.42,.7,mats.rust);box(g,.15,.58,0,.5,.18,.42,mats.metal);box(g,-.24,.5,.15,.28,.2,.24,mats.dark)}else if(type==='crystal'){const c=new THREE.Mesh(new THREE.OctahedronGeometry(.48,0),mats.blue);c.position.y=.48;c.castShadow=true;g.add(c);box(g,0,.08,0,.65,.16,.65,mats.dark)}else{cylinder(g,0,.35,0,.33,.24,.7,mats.wood,5);box(g,0,.75,0,.4,.45,.4,mats.leaf)}game.resources.push(g)}
for(let i=0;i<29;i++){let x,z;do{x=(Math.random()-.5)*45;z=(Math.random()-.5)*45}while(Math.abs(x)<5&&Math.abs(z)<5);createResource(x,z,['scrap','scrap','fiber','crystal'][Math.floor(Math.random()*4)])}
function spawnEnemy(x,z){const g=new THREE.Group();g.position.set(x,0,z);g.userData={hp:80+game.kills*4,maxHp:80+game.kills*4,attack:0,speed:1.25+Math.random()*.32};scene.add(g);
 box(g,0,1.05,0,.68,.82,.46,mats.enemy);box(g,0,1.62,0,.55,.42,.5,mats.dark);box(g,0,1.63,-.27,.28,.08,.03,mats.enemyGlow);box(g,0,.75,-.26,.45,.3,.08,mats.rust);
 for(const side of [-1,1]){box(g,side*.44,1,0,.2,.45,.35,mats.dark);box(g,side*.18,.32,0,.22,.6,.28,mats.enemy);box(g,side*.18,.08,-.03,.28,.14,.36,mats.dark)}
 const core=new THREE.PointLight('#ff3d25',.8,4);core.position.y=1.55;g.add(core);const healthBack=box(g,0,2.15,0,.9,.08,.06,mats.dark,false);const health=box(g,0,2.16,-.04,.84,.04,.03,mats.enemyGlow,false);g.userData.healthBar=health;game.enemies.push(g);return g}
function spawnWave(){for(let i=0;i<4+Math.min(4,Math.floor(game.kills/3));i++){let a=Math.random()*Math.PI*2,r=19+Math.random()*8;spawnEnemy(Math.cos(a)*r,Math.sin(a)*r)}ui.wave.textContent=String(1+Math.floor(game.kills/8)).padStart(2,'0')}
spawnWave();
function notify(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function updateHud(){ui.credits.textContent=game.credits;ui.kills.textContent=game.kills;ui.objective.style.width=`${Math.min(100,game.kills/8*100)}%`;ui.health.style.width=`${Math.max(0,game.hp)}%`;ui.healthText.textContent=Math.ceil(game.hp);ui.armor.style.width=`${Math.max(0,Math.min(100,game.armor/game.armorMax*100))}%`;ui.armorText.textContent=Math.ceil(game.armor);ui.xp.style.width=`${game.xp}%`;ui.xpText.textContent=`${game.xp} / 100`;ui.classLabel.textContent=`${classes.find(c=>c.id===game.classId).name} · LV ${String(game.level).padStart(2,'0')}`;ui.ammo.innerHTML=`${game.ammo} <i>/</i> ${game.reserve}`;ui.resources.textContent=`${game.scrap} SCRAP · ${game.crystal} CRYSTAL · ${game.fiber} FIBER`}
function damagePlayer(amount){if(game.armor>0){const absorbed=Math.min(game.armor,amount*.65);game.armor-=absorbed;amount-=absorbed}game.hp=Math.max(0,game.hp-amount);game.lastDamage=performance.now();$('#damage-flash').style.opacity='.8';setTimeout(()=>$('#damage-flash').style.opacity='0',150);if(game.hp<=0){game.hp=100;game.armor=Math.floor(game.armorMax*.35);player.position.set(0,0,4);game.credits=Math.max(0,game.credits-35);notify('OPERATIVE DOWN — RESPAWNED · 35¢ LOST')}updateHud()}
function killEnemy(enemy){scene.remove(enemy);game.enemies=game.enemies.filter(e=>e!==enemy);game.kills++;game.xp+=25;if(game.classId==='recon')game.credits+=22;else game.credits+=15;game.scrap+=game.classId==='engineer'?4:2;game.credits+=Math.floor(Math.random()*7);if(game.xp>=100){game.xp-=100;game.level++;game.hp=Math.min(100,game.hp+20);notify(`FIELD PROMOTION — LEVEL ${game.level}`)}else notify('HOSTILE DOWN · SALVAGE +15¢');updateHud();if(game.enemies.length===0)setTimeout(spawnWave,2200)}
function shoot(){if(!game.started||game.terminal||game.reload||game.fireTimer>0)return;if(game.ammo<=0){notify('MAGAZINE EMPTY · PRESS R');return}game.ammo--;game.fireTimer=game.weapon==='Pulse Carbine'?.24:.12;muzzleFlash.intensity=4;setTimeout(()=>muzzleFlash.intensity=0,45);
 raycaster.setFromCamera(mouseNdc,camera);const targets=[];for(const enemy of game.enemies){enemy.traverse(o=>{if(o.isMesh)targets.push(o)})}const hit=raycaster.intersectObjects(targets,false)[0];if(hit){let e=hit.object;while(e.parent&&!game.enemies.includes(e))e=e.parent;if(game.enemies.includes(e)){const dmg=game.damage*(game.classId==='vanguard'?1.15:1);e.userData.hp-=dmg;e.userData.healthBar.scale.x=Math.max(.02,e.userData.hp/e.userData.maxHp);e.userData.healthBar.position.x=-(1-e.userData.hp/e.userData.maxHp)*.42;if(e.userData.hp<=0)killEnemy(e)}}updateHud()}
function reload(){if(game.reload||game.ammo>=30||game.reserve<=0)return;game.reload=true;notify('RELOADING…');setTimeout(()=>{const n=Math.min(30-game.ammo,game.reserve);game.ammo+=n;game.reserve-=n;game.reload=false;updateHud()},1100)}

