function reload(){if(game.reload||game.ammo>=30||game.reserve<=0)return;game.reload=true;notify('RELOADING…');setTimeout(()=>{const n=Math.min(30-game.ammo,game.reserve);game.ammo+=n;game.reserve-=n;game.reload=false;updateHud()},1100)}
function spend(cost){if(game.scrap<(cost.scrap||0)||game.crystal<(cost.crystal||0)||game.fiber<(cost.fiber||0))return false;game.scrap-=cost.scrap||0;game.crystal-=cost.crystal||0;game.fiber-=cost.fiber||0;return true}
function performCraft(action,cost){if(!spend(cost)){notify('INSUFFICIENT SALVAGE — FIND RESOURCES');return}if(action==='armor'){game.armor=Math.min(game.armorMax,game.armor+45)}if(action==='medkit'){game.hp=Math.min(100,game.hp+50)}if(action==='ammo'){game.reserve+=60}if(action==='rifle'){game.weapon='Pulse Carbine';game.damage=Math.max(game.damage,40);game.ammo=24;game.reserve+=72;$('#weapon-name').innerHTML='PULSE <span>02</span>';$('#weapon-kind').textContent='ENERGY CARBINE · MK II';}if(action==='wall'||action==='turret'){buildDeployable(action)}if(action==='armor2'){game.armorMax+=30;game.armor=Math.min(game.armorMax,game.armor+30)}if(action==='damage'){game.damage+=6}if(action==='speed'){game.speed+=.12}notify('FABRICATION COMPLETE · SALVAGE SPENT');updateHud();if(game.terminal)renderTerminal(game.selectedTab)}
function buildDeployable(type){const forward=new THREE.Vector3(0,0,-1).applyQuaternion(player.quaternion);const pos=player.position.clone().add(forward.multiplyScalar(3));if(type==='wall'){const g=new THREE.Group();g.position.copy(pos);g.rotation.y=player.rotation.y;scene.add(g);box(g,0,.8,0,3.8,1.6,.55,mats.metal);box(g,0,1.65,0,3.9,.12,.62,mats.lime);game.buildings.push(g)}else{const g=new THREE.Group();g.position.copy(pos);scene.add(g);box(g,0,.45,0,.9,.9,.9,mats.metal);cylinder(g,0,1,0,.18,.18,.9,mats.rust,8);const light=new THREE.PointLight('#d4fa55',1,5);light.position.y=1.3;g.add(light);g.userData.nextShot=0;game.buildings.push(g)} }
function costMarkup(cost){return `<div class="cost"><span>${cost.scrap||0} SCRAP</span><span>${cost.crystal||0} CRYSTAL</span><span>${cost.fiber||0} FIBER</span></div>`}
function renderTerminal(tab='classes'){game.selectedTab=tab;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===tab));if(tab==='classes'){ui.content.innerHTML=`<div class="class-grid">${classes.map(c=>`<article class="class-card ${game.classId===c.id?'selected':''}"><div class="class-icon">${c.icon}</div><h3>${c.name}</h3><div class="role">${c.role}</div><p>${c.desc}</p><div class="stat-line"><span>VITALS</span><b>${c.hp}</b></div><div class="stat-line"><span>ARMOR</span><b>${c.armor}</b></div><div class="stat-line"><span>FIELD PERK</span><b>${c.perk}</b></div><button data-class="${c.id}">${game.classId===c.id?'ACTIVE LOADOUT':'SELECT CLASS'}</button></article>`).join('')}</div>`}
 else if(tab==='craft'||tab==='armory'){const items=tab==='craft'?recipes:armory;ui.content.innerHTML=`<div class="recipe-grid">${items.map(r=>`<article class="item-card"><div class="item-icon">${r.icon}</div><div><h3>${r.name}</h3><p>${r.desc}</p>${costMarkup(r.cost)}</div><button data-action="${r.action}" data-cost='${JSON.stringify(r.cost)}'>${r.action==='wall'||r.action==='turret'?'BUILD':'CRAFT'}</button></article>`).join('')}</div>`}
 else {ui.content.innerHTML=`<div class="inventory-layout"><div><h3 class="section-title">CARRIED RESOURCES</h3><div class="inventory-slots"><div class="slot">▧<small>SCRAP · ${game.scrap}</small></div><div class="slot" style="color:#73bdd0">◇<small>CRYSTAL · ${game.crystal}</small></div><div class="slot" style="color:#94b470">▣<small>FIBER · ${game.fiber}</small></div><div class="slot">⌁<small>${game.weapon.toUpperCase()}</small></div><div class="slot" style="color:#75c5e0">⬡<small>ARMOR · ${Math.floor(game.armor)}/${game.armorMax}</small></div><div class="slot">✚<small>FIELD MEDKIT</small></div></div></div><div><h3 class="section-title">OPERATIVE PROFILE</h3><div class="item-card"><div class="item-icon">✳</div><div><h3>${classes.find(c=>c.id===game.classId).name}</h3><p>FIELD LEVEL ${game.level}<br/>COMBAT XP ${game.xp}/100<br/>NEUTRALIZED ${game.kills} HOSTILES</p></div></div><div class="empty-state" style="margin-top:12px">FIELD SALVAGE IS YOUR CURRENCY.<br/>HARVEST RESOURCE CACHE NODES AROUND THE OUTPOST.</div></div></div>`}updateHud()}
function openTerminal(tab){game.terminal=true;ui.terminal.classList.remove('hidden');renderTerminal(tab);document.exitPointerLock?.()}
function closeTerminal(){game.terminal=false;ui.terminal.classList.add('hidden')}
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>renderTerminal(t.dataset.tab)));
ui.content.addEventListener('click',e=>{const cl=e.target.closest('[data-class]');if(cl){const c=classes.find(q=>q.id===cl.dataset.class);game.classId=c.id;game.hp=c.hp;game.armorMax=c.armor+(game.armorMax>35?game.armorMax-25:0);game.armor=Math.min(game.armorMax,c.armor);game.speed=c.speed;game.weapon=c.weapon;game.damage=c.id==='vanguard'?28.75:25;game.ammo=30;$('#weapon-name').innerHTML=`${c.weapon} <span>01</span>`;$('#weapon-kind').textContent=c.id==='ranger'?'PRECISION RIFLE · MK I':'ASSAULT RIFLE · MK I';renderTerminal('classes');notify(`${c.name} LOADOUT EQUIPPED`);return}const btn=e.target.closest('[data-action]');if(btn)performCraft(btn.dataset.action,JSON.parse(btn.dataset.cost))});
$('#deploy').addEventListener('click',()=>{game.started=true;$('#start-screen').classList.add('hidden');renderer.domElement.requestPointerLock?.();notify('DEPLOYED · SECURE THE OUTPOST')});$('#menu-open').addEventListener('click',()=>openTerminal('classes'));$('#menu-close').addEventListener('click',closeTerminal);

